sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var cpf = newValue.replace(/\D/g, '');
    var message;

    // Se o usuário digitou mas tem menos de 11 dígitos
    if (cpf.length > 0 && cpf.length < 11) {
        // Evita chamar setValue se já estiver limpo
        if (newValue !== '') {
            g_form.setValue('u_cpf_solicitante', '');
        }

        getMessage('cpf_incompleto_msg', function (msg) {
            message = msg.replace('{0}', newValue);
            g_form.showFieldMsg('u_cpf_solicitante', message, 'error', true);
        });
        return;
    }

    // Se atingiu 11 dígitos, formata e valida no servidor via Script Include
    if (cpf.length === 11) {
        var cpfFormatado = cpf.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4');

        // [TRAVA ANTI-LOOP] Se o valor digitado já é exatamente o CPF formatado, 
        // encerra aqui para evitar re-gatilhar o onChange infinitamente.
        if (newValue === cpfFormatado) {
            return;
        }

        g_form.setValue('u_cpf_solicitante', cpfFormatado);

        var ga = new GlideAjax('x_fub_fundbrad_ev.EVUtils');
        ga.addParam('sysparm_name', 'validarCPF');
        ga.addParam('sysparm_cpf', newValue);
        ga.getXMLAnswer(function (response) {
            if (response !== 'true') {
                g_form.setValue('u_cpf_solicitante', '');

                getMessage('cpf_invalido_msg', function (msg) {
                    message = msg.replace('{0}', newValue);
                    g_form.showFieldMsg('u_cpf_solicitante', message, 'error', true);
                });
            } else {
                g_form.hideFieldMsg('u_cpf_solicitante', true);
            }
        });
    }
}
